def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    rich_threat = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= budget:
                rich_threat += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, max(1.0, DAILY_SALARY * 0.35)))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = 2 if supply < WATER_REQ * 2 else 1
    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 2
    if no_water_days >= 2:
        urgency += 4
    elif no_water_days >= 1:
        urgency += 2
    if day >= 8:
        urgency += 1
    urgency += scarcity

    if urgency >= 8:
        target = max(95.0, highest_prev + 3.0)
    elif urgency >= 6:
        target = max(82.0, highest_prev + 1.5)
    elif urgency >= 4:
        if highest_prev >= 110:
            target = 72.0
        else:
            target = max(60.0, avg_prev * 0.78)
    else:
        if highest_prev >= 100:
            target = 28.0
        elif highest_prev >= 85:
            target = 42.0
        else:
            target = max(36.0, avg_prev * 0.6 if avg_prev > 0 else 38.0)

    if rich_threat >= 2 and urgency < 6:
        target *= 0.92
    if budget < 120:
        target = min(target, budget * (0.72 if urgency >= 6 else 0.5))
    elif budget < 220 and urgency < 6:
        target = min(target, budget * 0.42)

    if hp <= 2 or no_water_days >= 2:
        target = max(target, min(budget, highest_prev + 2.5 if highest_prev > 0 else 88.0))

    target = min(target, budget)
    if target < 0:
        target = 0.0
    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.5 # Default moderate bid

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        lowest_prev_bid = min(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.8:
            base_bid = max(base_bid, highest_prev_bid + 5)
        elif highest_prev_bid >= DAILY_SALARY * 0.6:
            base_bid = max(base_bid, highest_prev_bid + 2)
        else:
            base_bid = max(base_bid, lowest_prev_bid + 1)

    if my_status['hp'] <= 2:
        base_bid = max(base_bid, DAILY_SALARY * 0.95)
    elif my_status['hp'] <= 5:
        base_bid = max(base_bid, DAILY_SALARY * 0.8)

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2 and my_status['hp'] < WATER_REQ * 2:
        base_bid = max(base_bid, DAILY_SALARY * 0.9)
    elif remaining_days <= 4 and my_status['hp'] < WATER_REQ * 3:
        base_bid = max(base_bid, DAILY_SALARY * 0.7)

    num_agents_needing_water = 1
    for opp in alive_opponents:
        if opp['hp'] < WATER_REQ * 2:
            num_agents_needing_water += 1

    if day_context['supply'] < WATER_REQ * num_agents_needing_water:
        base_bid = base_bid * 1.1
        if my_status['hp'] <= 5:
            base_bid = base_bid * 1.15
    elif day_context['supply'] >= WATER_REQ * (1 + len(alive_opponents)) * 1.5:
        base_bid = base_bid * 0.9

    final_bid = min(my_status['budget'], base_bid)

    return max(0.0, final_bid)

